package org.telegram.ui.Components;

import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.view.animation.OvershootInterpolator;
import android.widget.*;
import org.telegram.messenger.*;
import org.telegram.ui.*;
import org.telegram.ui.ActionBar.*;

/** Exact compact/full reference geometry and timings, with swipe dismissal. */
public final class DevGramNoticePopup {
    private static View shown;
    private static Runnable timeout;
    private DevGramNoticePopup(){}
    private static int dp(float v){return AndroidUtilities.dp(v);}
    public static void remove(long id){if(shown!=null&&Long.valueOf(id).equals(shown.getTag()))hide();}
    public static void hide(){if(timeout!=null)AndroidUtilities.cancelRunOnUIThread(timeout);timeout=null;View previous=shown;shown=null;if(previous!=null){previous.animate().cancel();if(previous.getParent() instanceof ViewGroup)((ViewGroup)previous.getParent()).removeView(previous);}}
    public static void show(int account,DevGramCustomizationNotices.Item item){BaseFragment host=LaunchActivity.getSafeLastFragment();if(SharedConfig.appLocked||host==null||host.getCurrentAccount()!=account||host.getParentActivity()==null||!DevGramCustomizationNotices.allowed())return;View content=host.getParentActivity().findViewById(android.R.id.content);if(!(content instanceof FrameLayout))return;hide();boolean full=DevGramCustomizationNotices.full()||item.section==1;LinearLayout panel=new LinearLayout(content.getContext());panel.setGravity(Gravity.CENTER_VERTICAL);panel.setPadding(dp(full?14:6),dp(full?14:6),dp(full?16:14),dp(full?14:6));GradientDrawable back=new GradientDrawable();back.setColor(Theme.getColor(Theme.key_dialogBackground,host.getResourceProvider()));back.setCornerRadius(dp(full?22:24));panel.setBackground(back);panel.setElevation(dp(full?12:6));
        int side=full?42:26;panel.addView(face(host,item.who,side),LayoutHelper.createLinear(side,side));LinearLayout text=DevGramStudioControls.column(content.getContext());LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(full?0:-2,-2,full?1:0);tp.leftMargin=dp(full?10:8);panel.addView(text,tp);TextView title=DevGramStudioControls.text(content.getContext(),"",full?15:13,full,host.getResourceProvider());title.setText(item.title());title.setMaxLines(full?2:1);title.setEllipsize(android.text.TextUtils.TruncateAt.END);if(!full)title.setMaxWidth(dp(190));text.addView(title);
        if(full&&!item.text().isEmpty()){TextView body=DevGramStudioControls.text(content.getContext(),"",14,false,host.getResourceProvider());body.setText(item.text());body.setMaxLines(3);body.setEllipsize(android.text.TextUtils.TruncateAt.END);body.setLineSpacing(dp(2),1);body.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,host.getResourceProvider()));text.addView(body);}
        if(full){TextView read=DevGramStudioControls.text(content.getContext(),"Читать полностью",12,false,host.getResourceProvider());read.setTextColor(Theme.getColor(Theme.key_dialogTextBlue,host.getResourceProvider()));read.setPadding(0,dp(6),0,0);text.addView(read);text.post(()->{boolean overflow=false;for(int i=0;i<text.getChildCount()-1;i++){View child=text.getChildAt(i);if(child instanceof TextView){android.text.Layout layout=((TextView)child).getLayout();if(layout!=null&&layout.getLineCount()>0&&layout.getEllipsisCount(layout.getLineCount()-1)>0)overflow=true;}}read.setVisibility(overflow?View.VISIBLE:View.GONE);});}
        FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(full?-1:-2,-2,full?Gravity.TOP:Gravity.TOP|Gravity.RIGHT);p.leftMargin=full?dp(10):0;p.rightMargin=dp(10);p.topMargin=AndroidUtilities.statusBarHeight+dp(full?22:8);((FrameLayout)content).addView(panel,p);shown=panel;panel.setTag(item.id);panel.setAlpha(0);if(full){panel.setPivotX(dp(320));panel.setPivotY(0);panel.setScaleX(.28f);panel.setScaleY(.55f);panel.animate().scaleX(1).scaleY(1).alpha(1).setDuration(260).setInterpolator(new OvershootInterpolator(1.1f)).start();}else{panel.setTranslationY(-dp(10));panel.animate().translationY(0).alpha(1).setDuration(180).start();}
        panel.setOnClickListener(v->{hide();if(DevGramCustomizationNotices.allowed())DevGramNoticesSheet.item(host,item);});float[] down=new float[2];boolean[] moved={false};panel.setOnTouchListener((v,event)->{if(event.getActionMasked()==MotionEvent.ACTION_DOWN){down[0]=event.getRawX();down[1]=event.getRawY();moved[0]=false;}else if(event.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=event.getRawX()-down[0],dy=event.getRawY()-down[1];if(Math.abs(dx)>dp(8)||Math.abs(dy)>dp(8))moved[0]=true;if(moved[0]){v.setTranslationX(dx);v.setTranslationY(Math.min(0,dy));return true;}}else if(event.getActionMasked()==MotionEvent.ACTION_UP||event.getActionMasked()==MotionEvent.ACTION_CANCEL){if(moved[0]){away(panel);return true;}}return false;});DevGramStudioControls.haptic(panel,HapticFeedbackConstants.CLOCK_TICK);timeout=()->away(panel);AndroidUtilities.runOnUIThread(timeout,full?5000:1500);
    }
    private static void away(View panel){if(shown!=panel)return;panel.animate().alpha(0).translationY(-dp(10)).setDuration(180).withEndAction(()->{if(shown==panel)hide();}).start();}
    public static View face(BaseFragment host,long uid,int side){BackupImageView image=new BackupImageView(host.getParentActivity());image.setRoundRadius(dp(side/2f));org.telegram.tgnet.TLRPC.User user=host.getMessagesController().getUser(uid);AvatarDrawable drawable=new AvatarDrawable();if(user!=null){drawable.setInfo(user);image.setForUserOrChat(user,drawable);}else if(uid>0){drawable.setInfo(uid,Long.toString(uid),"");image.setImageDrawable(drawable);}else{ImageView bell=new ImageView(host.getParentActivity());bell.setImageResource(R.drawable.msg_notifications);bell.setScaleType(ImageView.ScaleType.CENTER);bell.setColorFilter(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText,host.getResourceProvider()));return bell;}return image;}
}
